import{f as e,o as a,c as o,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const u=JSON.parse('{"title":"Guía UI/UX para todo el desarrollo — CoopApps","description":"","frontmatter":{},"headers":[],"relativePath":"especificacion/GUIA-UI-UX-DESARROLLO.md","filePath":"especificacion/GUIA-UI-UX-DESARROLLO.md","lastUpdated":null}'),r={name:"especificacion/GUIA-UI-UX-DESARROLLO.md"};function n(i,t,c,s,l,p){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="guia-ui-ux-para-todo-el-desarrollo-—-coopapps" tabindex="-1">Guía UI/UX para todo el desarrollo — CoopApps <a class="header-anchor" href="#guia-ui-ux-para-todo-el-desarrollo-—-coopapps" aria-label="Permalink to &quot;Guía UI/UX para todo el desarrollo — CoopApps&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Versión</td><td>1.1</td></tr><tr><td>Fecha</td><td>19-11-2026</td></tr><tr><td>Estado</td><td>Vigente</td></tr><tr><td>Audiencia</td><td>Desarrollo front y full stack, diseño, QA, export GoodApps</td></tr></tbody></table><blockquote><p><strong>Documento de entrada.</strong> Esta guía es el <strong>apartado exclusivo</strong> de UI/UX para implementar cualquier pantalla, flujo o componente. Stack UI vigente: <strong>React 19</strong> (DEC-113). El detalle normativo completo vive en <strong><code>anexos/T03-UXD-experiencia-marca-diccionario.md</code></strong>. Export al cliente: redacción afirmativa según <strong>DIR-13</strong> en <code>06-impacto-adaptacion-stack-goodapps.md</code>.</p></blockquote><h2 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h2><ol><li><a href="#1-jerarquía-documental">Jerarquía documental</a></li><li><a href="#2-aplicaciones-y-shell-obligatorio">Aplicaciones y shell obligatorio</a></li><li><a href="#3-checklist-por-pantalla-nueva">Checklist por pantalla nueva</a></li><li><a href="#4-reglas-no-negociables">Reglas no negociables</a></li><li><a href="#5-tokens-y-temas-resumen">Tokens y temas (resumen)</a></li><li><a href="#6-componentes-usar-solo-el-catálogo">Componentes: usar solo el catálogo</a></li><li><a href="#7-reglas-ux-transversales">Reglas UX transversales</a></li><li><a href="#8-diccionario-y-microcopy">Diccionario y microcopy</a></li><li><a href="#9-marca-en-runtime">Marca en runtime</a></li><li><a href="#10-ayuda-al-usuario">Ayuda al usuario</a></li><li><a href="#11-ia-en-la-interfaz">IA en la interfaz</a></li><li><a href="#12-accesibilidad-mínima-wcag-22-aa">Accesibilidad mínima (WCAG 2.2 AA)</a></li><li><a href="#13-antipatrones-prohibidos">Anti‑patrones prohibidos</a></li><li><a href="#14-stack-de-implementación">Stack de implementación</a></li><li><a href="#15-mapa-de-profundidad-en-t03">Mapa de profundidad en T03</a></li></ol><hr><h2 id="_1-jerarquia-documental" tabindex="-1">1. Jerarquía documental <a class="header-anchor" href="#_1-jerarquia-documental" aria-label="Permalink to &quot;1. Jerarquía documental&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prioridad</th><th>Documento</th><th>Uso en desarrollo</th></tr></thead><tbody><tr><td>1</td><td><strong>Esta guía</strong></td><td>Decisiones diarias: qué shell, qué componente, qué regla</td></tr><tr><td>1b</td><td><strong><code>08-identidad-marca-coopapps.md</code></strong></td><td>Paleta y logos del <strong>producto</strong> CoopApps; assets <code>docs/brand/coopapps/</code></td></tr><tr><td>2</td><td><strong>T03 UXD</strong></td><td>Tokens, RF-UXD-<em>, catálogo §10.2, mapa del sitio §10.8, pantallas PAN-UXD-</em></td></tr><tr><td>3</td><td><strong><code>00-ESPECIFICACION-MAESTRA.md</code> §8–11</strong></td><td>Resumen de apps, layouts y design system</td></tr><tr><td>4</td><td><strong>Anexo del módulo</strong> (M01…M19, T*)</td><td>Contenido funcional: campos, flujos, <code>PAN-&amp;lt;COD&gt;-NN</code>, capabilities</td></tr><tr><td>5</td><td><strong>CNX</strong> (<code>referencia-connectia/…</code>)</td><td>Referencia histórica Connectia; prevalencia vía T03</td></tr><tr><td>6</td><td><strong><code>06-impacto-adaptacion-stack-goodapps.md</code></strong></td><td>Adaptación marca/stack (CoopApps, React, SQL); no recorta UX</td></tr></tbody></table><p><strong>Regla:</strong> Los módulos <strong>no inventan</strong> layouts ni componentes paralelos. Describen la pantalla en su anexo; la <strong>forma</strong> la cumple T03 + esta guía.</p><hr><h2 id="_2-aplicaciones-y-shell-obligatorio" tabindex="-1">2. Aplicaciones y shell obligatorio <a class="header-anchor" href="#_2-aplicaciones-y-shell-obligatorio" aria-label="Permalink to &quot;2. Aplicaciones y shell obligatorio&quot;">​</a></h2><p>Toda ruta debe montarse dentro de <strong>un solo</strong> MainLayout según la app:</p><table tabindex="0"><thead><tr><th>App</th><th>Paquete / meta</th><th>Layout</th><th>API base</th></tr></thead><tbody><tr><td>Admin cooperativa</td><td><code>apps/admin</code>, <code>meta.tenantOnly</code></td><td><code>AdminShell</code> + página §10.1.2</td><td><code>/api/admin/*</code></td></tr><tr><td>Consola plataforma</td><td><code>meta.platformOnly</code></td><td><code>PlatformShell</code></td><td><code>/api/platform/*</code></td></tr><tr><td>PWA socio / empleado / campo</td><td><code>apps/pwa</code></td><td><code>AppShell</code> + <code>.pwa-mod</code> en contenido</td><td><code>/api/*</code></td></tr><tr><td>Landing pública</td><td><code>apps/landing</code></td><td><code>LandingLayout</code></td><td><code>/api/public/{slug}/*</code></td></tr></tbody></table><p>Diagramas y zonas: <strong>T03 §10.1</strong> (<code>AdminShell</code>, <code>AppShell</code>, <code>ScreenHelp</code>, tabbar, FAB).</p><table tabindex="0"><thead><tr><th>Principio</th><th>Referencia</th></tr></thead><tbody><tr><td>Un <strong>H1</strong> por vista (PWA)</td><td>RF-UXD-017</td></tr><tr><td><strong>Una tarea principal</strong> por pantalla (socio)</td><td>BASE §102.5.6</td></tr><tr><td>Menú lateral = mismo árbol que mapa del sitio y perfiles T02</td><td>RF-UXD-047</td></tr><tr><td>PWA en escritorio: <strong>phone shell</strong> 430 px (salvo excepción PA-UXD-11)</td><td>T03 §10.1.4</td></tr></tbody></table><hr><h2 id="_3-checklist-por-pantalla-nueva" tabindex="-1">3. Checklist por pantalla nueva <a class="header-anchor" href="#_3-checklist-por-pantalla-nueva" aria-label="Permalink to &quot;3. Checklist por pantalla nueva&quot;">​</a></h2><p>Completar <strong>antes</strong> de dar por cerrada una <code>PAN-&amp;lt;COD&gt;-NN</code> (en PR o export):</p><ul><li>[ ] <strong><code>screenId</code></strong> estable y entrada en <code>siteMapGroups</code> (código versionado, T03 §10.8).</li><li>[ ] Ruta registrada; capability de <strong>ver</strong> alineada con T02 (<code>modulo.recurso.ver</code>).</li><li>[ ] Contenido dentro del <strong>shell</strong> correcto (§2).</li><li>[ ] Títulos, botones, vacíos y errores solo vía <strong><code>dict:&amp;lt;clave&gt;</code></strong> (sin literales en UI).</li><li>[ ] Listado admin: <strong><code>DataTable</code></strong> (no tabla custom). Listado PWA: <strong><code>ListCard</code></strong> con anatomía §10.3.1.</li><li>[ ] Alta PWA: <strong>modal desde FAB</strong>, sin ruta <code>/nuevo</code> (RF-UXD-099).</li><li>[ ] <strong><code>ScreenHelp</code></strong> base (6 preguntas + CU) o enlace explícito a CU en spec.</li><li>[ ] Estados: carga (skeleton), vacío (ilustración + acción), error (reintentar + <code>requestId</code>).</li><li>[ ] Formularios: errores <strong>inline</strong> + resumen; dinero con <strong><code>MoneyInput</code></strong>; fechas <code>dd-mm-yyyy</code>.</li><li>[ ] Acciones destructivas: <strong><code>ConfirmDialog</code></strong> / <strong><code>ConfirmSheet</code></strong>; económicas críticas con confirmación por tipeo.</li><li>[ ] Accesibilidad: foco en modales, labels, contraste, teclado en flujo principal.</li><li>[ ] Caso de prueba CP-* que cite el RF del módulo y un RF-UXD aplicable.</li></ul><hr><h2 id="_4-reglas-no-negociables" tabindex="-1">4. Reglas no negociables <a class="header-anchor" href="#_4-reglas-no-negociables" aria-label="Permalink to &quot;4. Reglas no negociables&quot;">​</a></h2><ol><li><strong>Cero texto fijo visible</strong> fuera del diccionario (RF-UXD-141/142). El CI debe rechazar literales en plantillas.</li><li><strong>Cero tablas admin ad hoc</strong> (RF-UXD-082). Vistas guardadas y export sobre el mismo <code>DataTable</code>.</li><li><strong>Cero menú duplicado</strong>: una fuente <code>siteMapGroups</code> (RF-UXD-047).</li><li><strong>Cero <code>alert()</code> del navegador</strong> (RF-UXD-102).</li><li><strong>Cero importes con <code>Number</code> de JS</strong> en UI (RF-UXD-087; ver convenciones de dinero en maestra §13).</li><li><strong>Cero color como único indicador de estado</strong> (RF-UXD-091): ícono + texto.</li><li><strong>Cero publicación directa desde IA</strong> (RF-UXD-052): borrador marcado «Propuesta de IA».</li><li><strong>Marca CoopApps</strong> en login/splash/manifest; cooperativa en operación (DEC-109, T03 §1.1).</li></ol><hr><h2 id="_5-tokens-y-temas-resumen" tabindex="-1">5. Tokens y temas (resumen) <a class="header-anchor" href="#_5-tokens-y-temas-resumen" aria-label="Permalink to &quot;5. Tokens y temas (resumen)&quot;">​</a></h2><p>Detalle completo: <strong>T03 §7.A</strong>.</p><h3 id="admin-data-theme-en-lt-html" tabindex="-1">Admin (<code>data-theme</code> en <code>&amp;lt;html&gt;</code>) <a class="header-anchor" href="#admin-data-theme-en-lt-html" aria-label="Permalink to &quot;Admin (`data-theme` en `&amp;lt;html&gt;`)&quot;">​</a></h3><ul><li>Oscuro por defecto: <code>--canvas #111019</code>, <code>--panel #1e1a2b</code>, <code>--brand #6b5bf0</code>, estados <code>ok/warn/bad</code>, radios <code>--r 12px</code> / <code>--r-s 9px</code>.</li><li>Tipografías: <strong>Space Grotesk</strong> (títulos), <strong>IBM Plex Sans</strong> (cuerpo), <strong>IBM Plex Mono</strong> (importes, códigos, tabular).</li><li>Componentes consumen <strong>tokens CSS</strong>; hex literales solo en <code>tokens.css</code>.</li></ul><h3 id="pwa-pwa-mod-tema-global" tabindex="-1">PWA (<code>.pwa-mod</code> + tema global) <a class="header-anchor" href="#pwa-pwa-mod-tema-global" aria-label="Permalink to &quot;PWA (`.pwa-mod` + tema global)&quot;">​</a></h3><ul><li>Fondo glow obligatorio; tokens <code>--pwa-brand</code>, <code>--pwa-lilac</code>, <code>--pwa-line</code>, radios 14/18 px.</li><li>Tipografía: <strong>Sora</strong> (stack CNX); importes con cifras tabulares.</li><li>Login y splash <strong>siempre oscuros</strong> (RF-UXD-016).</li></ul><h3 id="marca-del-tenant" tabindex="-1">Marca del tenant <a class="header-anchor" href="#marca-del-tenant" aria-label="Permalink to &quot;Marca del tenant&quot;">​</a></h3><p>Solo pisan variables de marca (<code>applyBrandingCssVars</code>, RF-UXD-025); el resto hereda del design system.</p><hr><h2 id="_6-componentes-usar-solo-el-catalogo" tabindex="-1">6. Componentes: usar solo el catálogo <a class="header-anchor" href="#_6-componentes-usar-solo-el-catalogo" aria-label="Permalink to &quot;6. Componentes: usar solo el catálogo&quot;">​</a></h2><p>Catálogo normativo: <strong>T03 §10.2</strong> (134 componentes). Agrupaciones:</p><table tabindex="0"><thead><tr><th>Necesidad</th><th>Componente(s)</th><th>§ T03</th></tr></thead><tbody><tr><td>Listado backoffice</td><td><code>DataTable</code>, <code>DataTableToolbar</code>, <code>FilterBar</code>, <code>BulkActionBar</code></td><td>10.2.2</td></tr><tr><td>Listado PWA</td><td><code>ListCard</code>, <code>PwaFilters</code>, <code>InfiniteList</code> / paginación</td><td>10.2.2, 10.3.1</td></tr><tr><td>Ficha entidad</td><td><code>EntityDetailLayout</code>, <code>Timeline</code>, <code>StatusBadge</code></td><td>10.2.2</td></tr><tr><td>Formulario</td><td><code>FormField</code>, <code>MaskedInput</code>, <code>MoneyInput</code>, <code>DateInput</code>, <code>EntityPicker</code>, <code>AddressPicker</code></td><td>10.2.3</td></tr><tr><td>Import masivo</td><td><code>ExcelImportWizard</code></td><td>10.2.3, RF-UXD-083</td></tr><tr><td>Feedback</td><td><code>ToastHost</code>, <code>ConfirmDialog</code>, <code>ConfirmSheet</code>, <code>JobProgress</code></td><td>10.2.4</td></tr><tr><td>Comunicaciones</td><td><strong><code>AudiencePicker</code> único</strong> (no duplicar)</td><td>RF-UXD-086</td></tr><tr><td>BI</td><td><code>BiKpiGrid</code>, vacío honesto, tabla alternativa en gráficos</td><td>10.2.5, RF-UXD-010</td></tr><tr><td>Offline campo</td><td><code>PwaOfflinePendingBanner</code>, <code>useOfflineQueue</code></td><td>10.2.4, RF-UXD-095</td></tr></tbody></table><p>Si falta un componente, se <strong>extiende</strong> <code>packages/ui</code> con historia en catálogo interno (<code>/plataforma/design-system</code>, RF-UXD-097), no se copia en el módulo.</p><p><strong>Composables obligatorios</strong> (10.2.7): <code>dict()</code>, <code>formatDate</code>, <code>formatMoney</code>, <code>useToast</code>, <code>useConfirm</code>, <code>notifKinds</code>, <code>useCreateAction</code> (FAB), <code>useBranding</code>, <code>useSiteMap</code>.</p><hr><h2 id="_7-reglas-ux-transversales" tabindex="-1">7. Reglas UX transversales <a class="header-anchor" href="#_7-reglas-ux-transversales" aria-label="Permalink to &quot;7. Reglas UX transversales&quot;">​</a></h2><p>Resumen de <strong>T03 §5.8</strong> y <strong>§10.3.2</strong>:</p><table tabindex="0"><thead><tr><th>Tema</th><th>Regla</th></tr></thead><tbody><tr><td>Carga</td><td>3 skeleton cards o 8 filas; refresh con opacidad, sin vaciar lista</td></tr><tr><td>Fechas visibles</td><td>Solo <code>formatDate</code> → <code>dd-mm-yyyy</code> (zona tenant)</td></tr><tr><td>Pestañas</td><td>Línea inferior (<code>TabsLine</code>); chips solo en barra de filtros</td></tr><tr><td>Vacíos</td><td>Ilustración + título comercial + CTA (<code>dict:ui.vacio.*</code>)</td></tr><tr><td>Paginación</td><td>Servidor <code>?page=&amp;size=</code>; export respeta filtros y alcance</td></tr><tr><td>Procesos largos</td><td>Barra de job, abandonable, aviso al terminar</td></tr><tr><td>Integraciones</td><td>Estados Pendiente / Confirmado / Fallido / Resultado incierto visibles</td></tr><tr><td>Microcopy PWA</td><td>Segunda persona («Ingresá», «Tenés»); todo por diccionario</td></tr><tr><td>Navegación PWA</td><td>Atrás del sistema cierra modal antes de salir de la ruta</td></tr></tbody></table><hr><h2 id="_8-diccionario-y-microcopy" tabindex="-1">8. Diccionario y microcopy <a class="header-anchor" href="#_8-diccionario-y-microcopy" aria-label="Permalink to &quot;8. Diccionario y microcopy&quot;">​</a></h2><ul><li>Resolver textos con <strong><code>dict(&#39;&amp;lt;clave&gt;&#39;)</code></strong> y fallback tenant → producto (T03 §5.11, §9).</li><li>Claves estables <code>namespace.objeto.variante</code>; tipos <code>term</code> | <code>label</code> | <code>message</code> | <code>help</code> | <code>legal</code>.</li><li>Pluralización y género: ICU subset / <code>{t:…}</code> (RF-UXD-145, RF-UXD-146).</li><li>Etiquetas de tabbar: variante <strong>corta</strong> ≤ 12 caracteres (RN-UXD-006).</li><li>Textos <strong>protegidos</strong> (fiscal/legal): no editables por tenant (RN-UXD-034).</li></ul><p>Editor y publicación: PAN-UXD-* en T03; mismos patrones borrador → publicado que T04.</p><hr><h2 id="_9-marca-en-runtime" tabindex="-1">9. Marca en runtime <a class="header-anchor" href="#_9-marca-en-runtime" aria-label="Permalink to &quot;9. Marca en runtime&quot;">​</a></h2><ul><li>Cargar marca pública sin PII: <code>GET /api/public/{slug}/branding</code>.</li><li>Aplicar: <code>applyBrandingCssVars</code>, <code>applyTenantPwaIdentity</code>, manifest dinámico, <code>theme-color</code> (RF-UXD-025–027).</li><li>Logos por <strong>canal</strong> (<code>admin</code>, <code>pwa-socio</code>, <code>landing</code>, <code>documentos</code>, …); jerarquía tenant → sucursal → producto.</li><li>Facturas y emails usan <code>brandAssets</code> canal <code>documentos</code> + diccionario.</li></ul><hr><h2 id="_10-ayuda-al-usuario" tabindex="-1">10. Ayuda al usuario <a class="header-anchor" href="#_10-ayuda-al-usuario" aria-label="Permalink to &quot;10. Ayuda al usuario&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Canal</th><th>Mecanismo</th><th>Dónde se configura</th></tr></thead><tbody><tr><td><strong>Todas las pantallas admin/PWA</strong></td><td><code>ScreenHelp</code> (<code>?</code>): qué/quién/cuándo/dónde/por qué/cómo + CU</td><td>T03 §10.1.3; editor PAN-UXD-06; <code>screenHelpArticles</code></td></tr><tr><td><strong>Landing / PWA ayuda</strong></td><td>FAQ por tema, bloque <code>faq</code></td><td>M19 PAN-POR-15, <code>/ayuda</code>, <code>/app/ayuda</code></td></tr><tr><td><strong>Bot</strong></td><td>Intención <code>faq</code> + lista Q&amp;A</td><td>M09 PAN-CRM-17</td></tr></tbody></table><p>No existe un <strong>FAQ global del ERP</strong> en admin: la cobertura operativa es <strong>ayuda por pantalla</strong> (ScreenHelp). Ver <code>06-impacto-adaptacion-stack-goodapps.md</code> §6.1 y <strong>§6.2</strong> (necesidad FAQ vs cobertura en todo el sistema; inventario en export).</p><hr><h2 id="_11-ia-en-la-interfaz" tabindex="-1">11. IA en la interfaz <a class="header-anchor" href="#_11-ia-en-la-interfaz" aria-label="Permalink to &quot;11. IA en la interfaz&quot;">​</a></h2><ul><li>Principio <strong>P6</strong> (maestra §1.3): la IA <strong>propone</strong>, la persona <strong>confirma</strong>; auditoría obligatoria.</li><li>UI: <code>AiProposalPanel</code>, <code>BiAiDrawer</code>, badge <code>dict:ui.ia.propuesta</code> (RF-UXD-052).</li><li>Asistente PWA: solo si flag <code>pwa.asistente</code> (T03 §10.1.4); dominio M09.</li></ul><hr><h2 id="_12-accesibilidad-minima-wcag-2-2-aa" tabindex="-1">12. Accesibilidad mínima (WCAG 2.2 AA) <a class="header-anchor" href="#_12-accesibilidad-minima-wcag-2-2-aa" aria-label="Permalink to &quot;12. Accesibilidad mínima (WCAG 2.2 AA)&quot;">​</a></h2><p>Objetivo <strong>RF-UXD-123</strong>. Checklist de entrega:</p><ul><li>[ ] Flujo principal operable solo con teclado (modales atrapan foco).</li><li>[ ] Contraste 4,5:1 texto / 3:1 UI con colores del tenant (RF-UXD-032, 125).</li><li>[ ] Labels + <code>aria-describedby</code> en campos; H1 único por vista.</li><li>[ ] Estado nunca solo por color (ícono + texto).</li><li>[ ] Objetivos táctiles ≥ 24 px (44 px recomendado en PWA).</li><li>[ ] <code>lang=&quot;es-AR&quot;</code>; <code>prefers-reduced-motion</code> respetado.</li><li>[ ] Ayuda <code>?</code> en la <strong>misma ubicación</strong> en todas las pantallas (RF-UXD-131).</li><li>[ ] Gráficos: botón «Ver como tabla».</li></ul><p>Matriz extendida: <strong>T03 §10.5</strong>.</p><hr><h2 id="_13-anti‐patrones-prohibidos" tabindex="-1">13. Anti‑patrones prohibidos <a class="header-anchor" href="#_13-anti‐patrones-prohibidos" aria-label="Permalink to &quot;13. Anti‑patrones prohibidos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anti‑patrón</th><th>Hacer en su lugar</th></tr></thead><tbody><tr><td>Tabla HTML propia en admin</td><td><code>DataTable</code> + vistas guardadas</td></tr><tr><td>Spinner centrado en lista PWA</td><td>3× <code>SkeletonCard</code></td></tr><tr><td>Ruta <code>/nuevo</code> en PWA</td><td>Modal + FAB</td></tr><tr><td>Segundo picker de audiencia</td><td><code>AudiencePicker</code> (T09 consume el mismo)</td></tr><tr><td>Menú hardcodeado por módulo</td><td>Ítem en <code>siteMapGroups</code></td></tr><tr><td><code>toLocaleDateString</code> suelto</td><td><code>formatDate</code></td></tr><tr><td>Subir archivos a carpeta pública</td><td><code>FileUploader</code> privado + URL firmada</td></tr><tr><td>KPI en 0 sin datos</td><td>Vacío honesto <code>dict:bia.vacio.honesto</code></td></tr><tr><td>Texto en español en JSX/TSX sin clave</td><td>Clave en catálogo + <code>dict()</code></td></tr><tr><td>Variante visual «porque es facturación»</td><td>Tokens y componentes compartidos</td></tr></tbody></table><hr><h2 id="_14-stack-de-implementacion" tabindex="-1">14. Stack de implementación <a class="header-anchor" href="#_14-stack-de-implementacion" aria-label="Permalink to &quot;14. Stack de implementación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Especificación</th><th>Nota</th></tr></thead><tbody><tr><td>UI normativa</td><td>T03 (comportamiento y tokens)</td><td>Independiente del framework</td></tr><tr><td>Stack vigente GoodApps</td><td>DEC-111, DEC-113</td><td><strong>.NET 10</strong>, <strong>React 19</strong>, <strong>shadcn/ui</strong> donde equivalga a componentes T03</td></tr><tr><td>Migración desde spec Vue/Connectia</td><td>T03 a reescribir ejemplos hacia React</td><td>Reglas de §4–13 <strong>no cambian</strong></td></tr></tbody></table><p>Implementación: biblioteca compartida (<code>packages/ui</code> o equivalente monorepo GoodApps) es dueña de componentes §10.2; apps solo componen pantallas.</p><hr><h2 id="_15-mapa-de-profundidad-en-t03" tabindex="-1">15. Mapa de profundidad en T03 <a class="header-anchor" href="#_15-mapa-de-profundidad-en-t03" aria-label="Permalink to &quot;15. Mapa de profundidad en T03&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesito…</th><th>Ir a T03</th></tr></thead><tbody><tr><td>RF completos UX</td><td>§5 (5.1–5.12)</td></tr><tr><td>Reglas de negocio UXD</td><td>§6</td></tr><tr><td>Tokens y colecciones UX</td><td>§7</td></tr><tr><td>Layouts y wire ASCII</td><td>§10.1</td></tr><tr><td>Lista de componentes</td><td>§10.2</td></tr><tr><td>Reglas de cards y modales</td><td>§10.3</td></tr><tr><td>Login paso a paso</td><td>§10.4</td></tr><tr><td>WCAG detallado</td><td>§10.5</td></tr><tr><td>Pantallas de configuración UXD</td><td>§10.6</td></tr><tr><td>Mapa del sitio completo (SM-*)</td><td>§10.8</td></tr><tr><td>APIs branding/diccionario/mapa</td><td>§11</td></tr><tr><td>Recorridos de prueba accesibilidad</td><td>§17</td></tr></tbody></table><hr><h3 id="bitacora" tabindex="-1">Bitácora <a class="header-anchor" href="#bitacora" aria-label="Permalink to &quot;Bitácora&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Cambio</th></tr></thead><tbody><tr><td>1.0</td><td>19-11-2026</td><td>Creación del apartado exclusivo; enlace desde maestra §11 y guía de anexos</td></tr><tr><td>1.1</td><td>19-11-2026</td><td>Enlace a <code>08-identidad-marca-coopapps.md</code> (DEC-119)</td></tr></tbody></table>',73)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
